INSERT INTO `kandidat` VALUES (3,2,1,'ARSYA & HADID','XI TM 3','VISI : \r\nMEMBENTUK SISWA YANG KRITIS DALAM BERFIKIR, SOPAN DALAM BERTINDAK, DAN KOMPAK DALAM KEBERSAMAAN\r\nMISI :\r\n•	MEMBERIKAN KESEMPATAN YANG SAMA BAGI SETIAP SISWA UNTUK BELAJAR DAN MENGEKSPRESIKAN DIRI\r\n•	MENJAGA LINGKUNGAN SEKOLAH YANG RAMAH, HANGAT, DAN BEBAS DARI TINDAKAN MEMBEDA-BEDAKAN\r\n•	MENAMPUNG IDE² KREATIF DARI SISWA UNTUK DIWUJUDKAN DALAM KEGIATAN YANG NYATA','6ad9d481dabc3.jpeg',1),(4,2,2,'DAYAT & ISRA','XI TM 1','VISI : \r\nMENJADIKAN OSIS SEBAGAI WADAH ASPIRASI, KREATIVITAS DAN KEMAJUAN BERSAMA YANG INKLUSIF INOVATIF DAN BERINTEGRITAS SERTA MENYEJAHTERAKAN SELURUH MASYARAKAT SEKOLAH SELARAS  DENGAN PERKEMBANGAN ZAMAN TANPA MELUPAKAN JATI DIRI BANGSA.\r\n\r\nMISI :\r\n1. Membuka Ruang Untuk Semua \r\n2. Mengembangkan Kreativitas Dan Bakat Tanpa Batas\r\n3. Membuat Sekolah Yang Nyaman Dan Bersaudara\r\n4. Menyeimbangkan Prestasi Akademik Dan Pengembangan Diri\r\n5. Mengikuti Zaman — Tetap Menjaga Identitas \r\n6. OSIS Yang Terbuka, Jujur, Dan Bekerja Nyata\r\n7. Menjadikan Sekolah Menjadi Rumah Yang Nyaman','6ad9d50c34efd.jpeg',1),(5,2,3,'DINDA & SALWA','X MPLB 1','VISI : \r\nMENTRANSFORMASI OSIS SEBAGAI PUSAT PERUBAHAN YANG ADAFTIF, SOLUTIF, KOLABORATIF DAN BERMANFAAT/BERDAMPAK NYATA BAGI SELURUH WARGA SEKOLAH.\r\nMISI :\r\n•	MEMPERKUAT INTREGRITAS DAN KARAKTER\r\n•	MENGAHADIRKAN PROGRAM KERJA YANG INOVATIF DAN KREATIF\r\n•	MEMPERKUAT KOLABORASI DAN SINERGI\r\n•	MENJADIKAN OSIS SEBAGAI ORGANISASI YANG SOLUTIF','6ad9d55ca79f6.jpeg',1),(6,12,2,'SYAHRUL & SUBHAEKI','X TM 3','-','6ad9dca16ac26.jpg',1),(7,12,1,'ARIF & RIZKY','X TM 4 & X TM 2','-','6ad9dd3a2b702.jpg',1),(8,9,1,'HERMAN','X TM 4','Visi:\r\nMenjadikan Rohis/Hadroh sebagai wadah untuk mempererat ukhuwah Islamiyah, meningkatkan keimanan, serta membentuk generasi yang berakhlak mulia melalui dakwah dan seni islami.\r\n\r\nMisi : \r\nMengembangkan kemampuan anggota dalam bidang hadroh dan dakwah Islam.','6ad9de1de1c99.jpg',1),(9,9,2,'AHMAD SAEPUL','X TM 2','Visi:\r\nMenjadikan Rohis/Hadroh sebagai generasi muda islami yang kreatif, inovatif, berkarakter, dan mampu menyebarkan nilai-nilai kebaikan di lingkungan sekolah.\r\n\r\nMisi :\r\nMeningkatkan partisipasi anggota dalam acara sekolah maupun kegiatan keagamaan.','6ad9de5fdfe15.jpg',1),(10,4,1,'DANIAL & DENDI','XI TM 3 & X TM 3','-','6ad9df173970c.jpg',1),(11,4,2,'IRFAN & RAKA','XI TM 3 & X TM 3','-','6ad9df4fe1c1f.jpg',1),(12,11,1,'SITI FATIMAH','XI MPLB 1','-','6adaa6205530f.jpeg',1),(13,11,2,'RISMA NURMALA','XI MPLB 1','-','6adaa63627215.jpeg',1);
/*!40000 ALTER TABLE `kandidat` ENABLE KEYS */;
