DROP TABLE IF EXISTS `siswa`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `siswa` (
  `id_siswa` int(11) NOT NULL AUTO_INCREMENT,
  `id_periode` int(11) NOT NULL,
  `nis` varchar(20) NOT NULL,
  `nama_siswa` varchar(100) NOT NULL,
  `kelas` varchar(50) NOT NULL,
  `pin` varchar(10) NOT NULL,
  `status_pilih` tinyint(1) DEFAULT 0,
  `status_aktif` tinyint(1) DEFAULT 1,
  `status_pkl` tinyint(1) DEFAULT 0,
  `tempat_pkl` varchar(150) DEFAULT NULL,
  `no_hp` varchar(25) DEFAULT NULL,
  `periode_pkl` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id_siswa`),
  KEY `id_periode` (`id_periode`),
  CONSTRAINT `siswa_ibfk_1` FOREIGN KEY (`id_periode`) REFERENCES `periode` (`id_periode`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=773 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
